package com.coffeeshop.model;
public final class CustomerModels{private CustomerModels(){}public record Customer(long id,String number,String firstName,String lastName,String legalName,String taxNumber,String phone,String email,String notes,boolean active,byte[]rowVersion){public Customer{rowVersion=rowVersion.clone();}@Override public byte[]rowVersion(){return rowVersion.clone();}public String displayName(){return (firstName+" "+(lastName==null?"":lastName)).trim();}}public record Option(long id,String number,String name){@Override public String toString(){return name+" ("+number+")";}}}
